#include <iostream>

class A {
public:
    using I = int;
    static constexpr I x = 42;
    I f() { return 0; }
    void g(I p = x) {
        std::cout << "Parameter p: " << p << std::endl;
    }
};

int main() {
    A a;
    a.g(); // Calls g() with default argument x
    a.g(10); // Calls g() with explicit argument 10
    return 0;
}
